// Smart-If: AI perceives, deterministic code decides. Same rules as the demo workflow.
const CONF_MIN = 0.6;
return $input.all().map((item) => {
  const a = item.json.answers;
  const ticket = $('Chat Trigger').first().json.chatInput;
  const urgent = a.urgent.noul;
  const team = a.team.choice;
  const conf = a.team.confidence;
  let route;
  if (conf < CONF_MIN) route = 'human_review';
  else if (urgent >= 0.7) route = 'page_oncall:' + team;
  else route = 'queue:' + team;
  return { json: { ticket, urgent, team, confidence: conf, route, output_tokens: item.json.usage.output_tokens, latency_ms: Math.round(item.json.total_duration / 1e6) } };
});

// The hosted chat replies with this item's `output` field (chat trigger response mode: last node).
return $input.all().map((item) => {
  const d = item.json;
  const lines = [
    'Routing decision',
    '',
    'Team: ' + d.team + ' (confidence ' + Number(d.confidence).toFixed(2) + ')',
    'Urgent: ' + Number(d.urgent).toFixed(2),
    'Route: ' + d.route,
    'ollaya latency: ' + d.latency_ms + ' ms (' + d.output_tokens + ' output tokens)',
  ];
  return { json: { output: lines.join('\n') } };
});

