// Model scores are signals for this demo, not a security guarantee.
const MALICIOUS_MIN = 0.7, INTENT_CONF_MIN = 0.6;
return $input.all().map((item) => {
  const a = item.json.answers || {};
  const intent = a.intent?.choice;
  const confidence = a.intent?.confidence;
  const malicious = a.malicious?.noul;
  const valid = ['support_ticket', 'casual_chat'].includes(intent)
    && typeof confidence === 'number' && Number.isFinite(confidence) && confidence >= 0 && confidence <= 1
    && typeof malicious === 'number' && Number.isFinite(malicious) && malicious >= 0 && malicious <= 1;
  let gate_route = 'unavailable';
  if (valid) {
    if (malicious >= MALICIOUS_MIN) gate_route = 'refuse';
    else if (confidence < INTENT_CONF_MIN) gate_route = 'clarify';
    else gate_route = intent === 'support_ticket' ? 'ticket' : 'casual';
  }
  return { json: {
    chatInput: $('Chat Trigger').first().json.chatInput,
    gate_route, intent, confidence, malicious,
    latency_ms: Number.isFinite(item.json.total_duration) ? Math.round(item.json.total_duration / 1e6) : null,
    output_tokens: item.json.usage?.output_tokens ?? null
  } };
});

// Hosted chat reads the last node's output field, just like Format Reply.
return $input.all().map((item) => {
  const d = item.json;
  const text = String(d.chatInput || '').trim();
  let reply;
  if (d.gate_route === 'refuse') reply = 'I can help with support questions, but not threats, abuse, or harmful requests. Please rephrase and I will try to help.';
  else if (d.gate_route === 'unavailable') reply = 'I could not check that message right now. Please try again in a moment.';
  else if (d.gate_route === 'clarify') reply = 'Could you tell me a little more? If you need support, describe the issue and I will help route it.';
  else if (/\b(thanks|thank you|cheers)\b/i.test(text)) reply = "You're welcome! What else can I help with?";
  else if (/\b(hi|hello|hey|good morning|good evening)\b/i.test(text)) reply = 'Hi there! How can I help today? We can chat, or you can tell me about a support issue.';
  else if (/\b(how are you|how.s it going)\b/i.test(text)) reply = "I'm here and ready to help! How is your day going?";
  else reply = 'Tell me a little more! If you have a support issue, describe it and I will help route it.';
  const lines = [reply];
  if (d.latency_ms !== null) lines.push('', 'System 1 gate: ' + d.latency_ms + ' ms (' + d.output_tokens + ' output tokens)');
  return { json: { output: lines.join('\n') } };
});

// A second opinion only when System 1 cannot confidently choose a team.
const s1 = $('Route Decision').first().json;
return $input.all().map((item) => {
  let d = null;
  try {
    const raw = String(item.json.response ?? '').replace(/```(?:json)?/gi, '').trim();
    d = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
    if (!['infra', 'billing', 'sales'].includes(d.team)
      || ![d.urgent, d.confidence].every(v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 1)) d = null;
  } catch (_) { d = null; }
  const lines = ['System 1 was unsure, so I asked System 2.', '',
    'S1 team confidence: ' + Number(s1.confidence).toFixed(2),
    'S1 triage latency: ' + s1.latency_ms + ' ms'];
  if (!d) {
    lines.push('System 2 did not return a usable answer. Please have a person review this ticket.', 'Route: human_review');
  } else {
    const route = d.confidence < 0.6 ? 'human_review' : d.urgent >= 0.7 ? 'page_oncall:' + d.team : 'queue:' + d.team;
    lines.push('Team: ' + d.team + ' (confidence ' + d.confidence.toFixed(2) + ')',
      'Urgent: ' + d.urgent.toFixed(2), 'Route: ' + route,
      'Ollama latency: ' + Math.round((item.json.total_duration || 0) / 1e6) + ' ms (' + (item.json.eval_count ?? '?') + ' output tokens)');
  }
  return { json: { output: lines.join('\n') } };
});
